"""Matrix, log, and resumable-chunk transitions owned by the spec-state writer."""
from __future__ import annotations

import re

from state_transition_common import (
    CANONICAL_PLATFORMS,
    CELL_STATES,
    PLATFORM_LABELS,
    TransitionError,
    empty_foundation,
    has_entry,
    normalize_serves,
)

CATEGORY_ID_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def derive_aggregate(cells: list[str]) -> str:
    if not cells or all(state == "未収集" for state in cells):
        return "未着手"
    if all(state == "対象外" for state in cells):
        return "対象外"
    if any(state == "未収集" for state in cells):
        return "収集中"
    return "確定"


def _row_states(state: dict, category_id: str) -> list[str]:
    return [state["matrix"][category_id][platform]["state"] for platform in CANONICAL_PLATFORMS]


def recompute_aggregates(state: dict) -> None:
    state["category_aggregate"] = {
        category["id"]: derive_aggregate(_row_states(state, category["id"]))
        for category in state["categories"]
    }


def count_unresolved(state: dict) -> int:
    return sum(
        cell.get("state") == "未収集"
        for row in state.get("matrix", {}).values()
        for cell in row.values()
        if isinstance(cell, dict)
    )


def _refresh_hearing_progress(state: dict) -> None:
    """Keep the resumable progress fields consistent with the matrix."""
    progress = state.setdefault("hearing_progress", {})
    unresolved = count_unresolved(state)
    progress["complete"] = unresolved == 0
    progress["next_question"] = None if unresolved == 0 else next_unresolved_question(state)


def bootstrap_state() -> dict:
    return {
        "schema_version": "1.0", "categories": [], "platforms": list(CANONICAL_PLATFORMS),
        "matrix": {}, "qa_log": [], "approval_log": [], "reopen_log": [],
        "category_aggregate": {}, "targets": [], "requirements_foundation": empty_foundation(),
        "decisions": [], "knowledge_candidates": [],
        "hearing_progress": {"loop_count": 0, "next_question": None, "complete": False},
    }


def init_state(taxonomy: dict, existing_state: dict | None = None) -> dict:
    if not isinstance(taxonomy, dict):
        raise TransitionError("taxonomy は object 必須")
    platforms = taxonomy.get("platforms")
    if not isinstance(platforms, list):
        raise TransitionError("taxonomy.platforms は配列必須")
    taxonomy_platforms = [item.get("id") for item in platforms if isinstance(item, dict)]
    if taxonomy_platforms != list(CANONICAL_PLATFORMS):
        raise TransitionError("taxonomy.platforms は canonical 6 platform と順序を一致させる必要がある")
    categories = taxonomy.get("categories")
    if not isinstance(categories, list) or not categories:
        raise TransitionError("taxonomy.categories は非空配列必須")
    ids = [item.get("id") for item in categories if isinstance(item, dict)]
    if len(ids) != len(categories) or len(set(ids)) != len(ids):
        raise TransitionError("taxonomy.categories の id が不正または重複")
    if existing_state and any(
        isinstance(cell, dict) and cell.get("state") == "確定"
        for row in existing_state.get("matrix", {}).values()
        if isinstance(row, dict)
        for cell in row.values()
    ):
        raise TransitionError(
            "init --state は matrix 未着手の bootstrap state 専用。"
            "確定セルを含む state の再初期化は R4-reopen を迂回するため拒否"
        )
    state = dict(existing_state or bootstrap_state())
    state["schema_version"] = "1.0"
    state["categories"] = [{"id": item["id"], "label": item["label"]} for item in categories]
    state["platforms"] = list(CANONICAL_PLATFORMS)
    state["matrix"] = {
        category["id"]: {platform: {"state": "未収集"} for platform in CANONICAL_PLATFORMS}
        for category in state["categories"]
    }
    state.setdefault("qa_log", [])
    state.setdefault("approval_log", [])
    state.setdefault("reopen_log", [])
    state.setdefault("targets", [])
    state.setdefault("requirements_foundation", empty_foundation())
    state.setdefault("decisions", [])
    state.setdefault("knowledge_candidates", [])
    state["hearing_progress"] = {"loop_count": 0, "next_question": None, "complete": False}
    recompute_aggregates(state)
    _refresh_hearing_progress(state)
    return state


def add_category(state: dict, category: dict) -> None:
    if not isinstance(category, dict):
        raise TransitionError("add-category: category は object 必須")
    category_id, label = category.get("id"), category.get("label")
    if not isinstance(category_id, str) or not category_id.strip():
        raise TransitionError("add-category: id が空")
    if not isinstance(label, str) or not label.strip():
        raise TransitionError("add-category: label が空")
    category_id, label = category_id.strip(), label.strip()
    if not CATEGORY_ID_RE.fullmatch(category_id):
        raise TransitionError(f"add-category: id は kebab-case 必須 ({category_id})")
    if category_id in state["matrix"] or any(item.get("id") == category_id for item in state["categories"]):
        raise TransitionError(f"add-category: 既存カテゴリ ({category_id}) の変更は R4-reopen 経由")
    state["categories"].append({"id": category_id, "label": label})
    state["matrix"][category_id] = {platform: {"state": "未収集"} for platform in CANONICAL_PLATFORMS}
    recompute_aggregates(state)
    _refresh_hearing_progress(state)


def _cell(state: dict, category: str, platform: str) -> dict:
    if category not in state["matrix"]:
        raise TransitionError(f"未知カテゴリ: {category}")
    if platform not in state["matrix"][category]:
        raise TransitionError(f"未知 platform: {platform} (カテゴリ {category})")
    return state["matrix"][category][platform]


def apply_cell_op(state: dict, op: dict) -> None:
    action, category, platform = op.get("action"), op.get("category"), op.get("platform")
    cell = _cell(state, category, platform)
    current = cell.get("state")
    if action == "reopen":
        if current != "確定":
            raise TransitionError(f"reopen 不可: {category}/{platform} は '{current}' (確定セルのみ reopen できる)")
        if not op.get("reason"):
            raise TransitionError(f"reopen には reason が必須: {category}/{platform}")
        discarded = {
            key: list(cell[key]) if isinstance(cell[key], list) else cell[key]
            for key in ("qa_ref", "serves_goals", "serves_intents")
            if key in cell
        }
        log_entry = {
            "category": category,
            "platform": platform,
            "reason": op["reason"],
            "from": "確定",
        }
        if discarded:
            log_entry["discarded"] = discarded
        state.setdefault("reopen_log", []).append(log_entry)
        state["matrix"][category][platform] = {"state": "未収集", "reopened_from": "確定", "reopen_reason": op["reason"]}
        return
    if action == "set-serves":
        if current != "確定":
            raise TransitionError(f"set-serves 不可: {category}/{platform} は '{current}' (確定セルのみ serves_goals を付与できる)")
        serves = normalize_serves(op.get("serves_goals"))
        if not serves:
            raise TransitionError(f"set-serves には非空 serves_goals が必須: {category}/{platform}")
        cell["serves_goals"] = serves
        return
    if current == "確定":
        raise TransitionError(f"確定セルの直接変更は拒否: {category}/{platform}。変更は R4-reopen を経由すること")
    if action == "confirm":
        if not op.get("qa_ref"):
            raise TransitionError(f"confirm には qa_ref が必須: {category}/{platform}")
        next_cell = {"state": "確定", "qa_ref": op["qa_ref"]}
        serves = normalize_serves(op.get("serves_goals"))
        if serves:
            next_cell["serves_goals"] = serves
        state["matrix"][category][platform] = next_cell
    elif action == "exclude":
        if not (op.get("reason") or op.get("approval_ref")):
            raise TransitionError(f"exclude には reason か approval_ref が必須: {category}/{platform}")
        next_cell = {"state": "対象外"}
        if op.get("reason"):
            next_cell["reason"] = op["reason"]
        if op.get("approval_ref"):
            next_cell["approval_ref"] = op["approval_ref"]
        state["matrix"][category][platform] = next_cell
    else:
        raise TransitionError(f"未知 action: {action!r}")


def set_targets(state: dict, targets: list) -> None:
    if not isinstance(targets, list):
        raise TransitionError(f"targets は配列でない: {targets!r}")
    normalized, seen = [], set()
    for target in targets:
        if isinstance(target, str):
            target_id, category = target, None
        elif isinstance(target, dict):
            target_id, category = target.get("target_id"), target.get("category")
        else:
            raise TransitionError(f"target は str か object でない: {target!r}")
        if not target_id:
            raise TransitionError(f"target に target_id が必須: {target!r}")
        if target_id in seen:
            raise TransitionError(f"target_id が重複: {target_id!r}")
        seen.add(target_id)
        entry = {"target_id": target_id}
        if category:
            entry["category"] = category
        normalized.append(entry)
    state["targets"] = normalized


def apply_turn(state: dict, turn: dict) -> None:
    qa_id = turn.get("qa_id")
    if qa_id and not has_entry(state["qa_log"], qa_id):
        entry = {"id": qa_id, "question": turn.get("question", ""), "answer": turn.get("answer", "")}
        if "source" in turn:
            entry["source"] = turn["source"]
        state["qa_log"].append(entry)
    approval_id = turn.get("approval_id")
    if approval_id and not has_entry(state["approval_log"], approval_id):
        state["approval_log"].append({"id": approval_id, "note": turn.get("approval_note", "")})
    for raw_op in turn.get("ops", []):
        op = dict(raw_op)
        if op.get("action") == "confirm" and not op.get("qa_ref") and qa_id:
            op["qa_ref"] = qa_id
        if op.get("action") == "exclude" and not op.get("reason") and not op.get("approval_ref") and approval_id:
            op["approval_ref"] = approval_id
        apply_cell_op(state, op)
    recompute_aggregates(state)
    _refresh_hearing_progress(state)


def next_unresolved_question(state: dict) -> str | None:
    labels = {category["id"]: category["label"] for category in state["categories"]}
    for category in state["categories"]:
        for platform in CANONICAL_PLATFORMS:
            cell = state["matrix"][category["id"]].get(platform)
            if cell and cell.get("state") == "未収集":
                return f"{labels.get(category['id'], category['id'])}（{category['id']}）× {PLATFORM_LABELS.get(platform, platform)}（{platform}）は対象ですか? 対象なら要件を、非対象なら理由を教えてください。"
    return None


def run_chunk(state: dict, turns: list[dict], max_loops: int = 5) -> int:
    processed = 0
    state["hearing_progress"]["loop_count"] = 0
    for turn in turns:
        if processed >= max_loops:
            break
        apply_turn(state, turn)
        processed += 1
        state["hearing_progress"]["loop_count"] = processed
    recompute_aggregates(state)
    _refresh_hearing_progress(state)
    state["hearing_progress"]["max_loops"] = max_loops
    return processed

"""Foundation and decision transitions for the spec-state single writer."""
from __future__ import annotations

from foundation_provenance import validate_foundation_source_indexes
from state_transition_common import (
    DECISION_COMPARISON_AXES,
    DECISION_COST_CATEGORIES,
    DECISION_OPTION_FIELDS,
    DECISION_STATUSES,
    FOUNDATION_KEYS,
    TransitionError,
    foundation_goal_ids,
    foundation_missing_fields,
    has_entry,
    is_explicit_na,
    is_https_url,
    is_rfc3339,
    normalize_serves,
    require_nonempty,
    require_nonempty_string_list,
)


def set_foundation(state: dict, foundation: dict) -> None:
    """Merge and confirm U1--U9 only after source, value, and approval gates pass."""
    if not isinstance(foundation, dict):
        raise TransitionError(f"requirements_foundation は object でない: {foundation!r}")
    foundation = dict(foundation)
    approval_note = foundation.pop("approval_note", None)
    approval_ref = foundation.get("approval_ref")
    if approval_ref and approval_note is not None:
        approvals = state.setdefault("approval_log", [])
        if not has_entry(approvals, approval_ref):
            approvals.append({"id": approval_ref, "note": approval_note})
    merged = dict(state.get("requirements_foundation") or {})
    for key, value in foundation.items():
        if key not in FOUNDATION_KEYS:
            raise TransitionError(f"requirements_foundation の未知キー: {key!r}")
        merged[key] = value
    scope = merged.get("scope")
    if scope is None:
        scope = {"in": [], "out": []}
    if not isinstance(scope, dict):
        raise TransitionError("requirements_foundation.scope は object でない")
    if not is_explicit_na(scope):
        scope.setdefault("in", [])
        scope.setdefault("out", [])
    merged["scope"] = scope
    goals = merged.get("goals", [])
    goal_ids = [] if is_explicit_na(goals) else foundation_goal_ids(goals)
    intents = merged.get("concrete_intents", []) or []
    if is_explicit_na(intents):
        intents = []
    elif not isinstance(intents, list):
        raise TransitionError("requirements_foundation.concrete_intents は配列でない")
    for intent in intents:
        if not isinstance(intent, dict):
            raise TransitionError(f"concrete_intent は object でない: {intent!r}")
        for goal_id in intent.get("serves", []) or []:
            if goal_id not in goal_ids:
                raise TransitionError(f"concrete_intent {intent.get('id')!r} の serves={goal_id!r} が実在 goal を指さない")
    confirmed = bool(merged.get("confirmed"))
    if confirmed:
        missing = foundation_missing_fields(merged)
        if missing:
            raise TransitionError("確定条件不足: U1-U3 は値必須・U4-U9 は値または明示 N/A+理由が必須: " + ", ".join(missing))
        approval_ref = merged.get("approval_ref")
        if not isinstance(approval_ref, str) or not approval_ref.strip():
            raise TransitionError("確定条件不足: confirmed には approval_ref (ユーザー合意の approval_log 参照) が必須")
        if not has_entry(state.get("approval_log") or [], approval_ref):
            raise TransitionError(f"確定条件不足: approval_ref={approval_ref!r} が approval_log に不在 (承認証跡なし)")
        source_findings = validate_foundation_source_indexes(state)
        if source_findings:
            raise TransitionError("確定条件不足: " + "; ".join(source_findings))
    merged["confirmed"] = confirmed
    state["requirements_foundation"] = merged


def _validate_cost_model(value, label: str) -> str:
    if not isinstance(value, dict):
        raise TransitionError(f"decision: {label} は object 必須")
    category = value.get("category")
    if category not in DECISION_COST_CATEGORIES:
        raise TransitionError(f"decision: {label}.category={category!r} が許容値外 ({sorted(DECISION_COST_CATEGORIES)})")
    amount = value.get("amount")
    if category == "unknown":
        if amount is not None and (isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0):
            raise TransitionError(f"decision: {label}.amount は非負数または null 必須")
    elif isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
        raise TransitionError(f"decision: {label}.amount は非負数必須")
    if category == "free" and amount != 0:
        raise TransitionError(f"decision: {label}.category=free の amount は 0 必須")
    if category in {"low-cost", "paid"} and amount == 0:
        raise TransitionError(f"decision: {label}.category={category} の amount は正数必須")
    for field in ("currency", "billing_period", "tco"):
        require_nonempty(value.get(field), f"{label}.{field}")
    return category


def set_decision(state: dict, decision: dict) -> None:
    if not isinstance(decision, dict):
        raise TransitionError("decision は object 必須")
    decision_id = decision.get("id")
    require_nonempty(decision_id, "id")
    require_nonempty(decision.get("question"), "question")
    status = decision.get("status")
    if status not in DECISION_STATUSES:
        raise TransitionError(f"decision: status={status!r} が許容値外")
    goal_ids = set(foundation_goal_ids((state.get("requirements_foundation") or {}).get("goals", [])))
    serves = normalize_serves(decision.get("serves_goals"))
    if not serves:
        raise TransitionError("decision: serves_goals は非空必須")
    dangling = [goal_id for goal_id in serves if goal_id not in goal_ids]
    if dangling:
        raise TransitionError(f"decision: serves_goals {dangling} が実在 goal を指さない")
    options = decision.get("options")
    if not isinstance(options, list) or not 2 <= len(options) <= 3:
        raise TransitionError("decision: options は2-3件必須")
    option_ids: list[str] = []
    cost_categories: set[str] = set()
    for option in options:
        if not isinstance(option, dict):
            raise TransitionError("decision option は object 必須")
        for field in DECISION_OPTION_FIELDS:
            if field != "cost_model":
                require_nonempty(option.get(field), f"option.{field}")
        cost_categories.add(_validate_cost_model(option.get("cost_model"), "option.cost_model"))
        for field in ("pros", "cons", "risks"):
            require_nonempty_string_list(option.get(field), f"option.{field}")
        evidence_refs = option.get("evidence_refs")
        require_nonempty_string_list(evidence_refs, "option.evidence_refs")
        if any(not is_https_url(ref) for ref in evidence_refs):
            raise TransitionError("decision: option.evidence_refs は公式 https URL 必須")
        if option["id"] in option_ids:
            raise TransitionError(f"decision: option id 重複 {option['id']!r}")
        option_ids.append(option["id"])
    if not cost_categories.intersection({"free", "low-cost"}):
        raise TransitionError("decision: options には free または low-cost 候補が最低1件必須")
    recommendation = decision.get("recommendation")
    if status != "needs_guidance":
        if not isinstance(recommendation, dict):
            raise TransitionError("decision: recommendation が必須")
        for field in ("option_id", "rationale", "caveats", "confidence", "latest_checked_at"):
            require_nonempty(recommendation.get(field), f"recommendation.{field}")
        require_nonempty_string_list(recommendation.get("caveats"), "recommendation.caveats")
        basis = recommendation.get("comparison_basis")
        if not isinstance(basis, dict):
            raise TransitionError("decision: recommendation.comparison_basis は object 必須")
        for axis in DECISION_COMPARISON_AXES:
            require_nonempty(basis.get(axis), f"recommendation.comparison_basis.{axis}")
        if not is_rfc3339(recommendation.get("latest_checked_at")):
            raise TransitionError("decision: recommendation.latest_checked_at は RFC3339 必須")
        if recommendation.get("option_id") not in option_ids:
            raise TransitionError("decision: recommendation.option_id が options に不在")
    user_decision = decision.get("user_decision")
    if status == "confirmed":
        if not isinstance(user_decision, dict):
            raise TransitionError("decision: confirmed には user_decision が必須")
        if user_decision.get("option_id") not in option_ids:
            raise TransitionError("decision: user_decision.option_id が options に不在")
        require_nonempty(user_decision.get("confirmed_at"), "user_decision.confirmed_at")
        if not is_rfc3339(user_decision.get("confirmed_at")):
            raise TransitionError("decision: user_decision.confirmed_at は RFC3339 必須")
    elif user_decision:
        raise TransitionError("decision: AI推奨だけで confirmed にせずユーザー確認を待つこと")
    normalized, records = dict(decision), list(state.get("decisions") or [])
    normalized["serves_goals"] = serves
    for index, current in enumerate(records):
        if isinstance(current, dict) and current.get("id") == decision_id:
            records[index] = normalized
            break
    else:
        records.append(normalized)
    state["decisions"] = records

"""Deterministic provenance checks for the U1--U9 foundation source indexes.

The state writer and the coverage validator both use this module so a prose
instruction cannot claim a foundation is traceable while the gate accepts an
unattributed confirmation.
"""
from __future__ import annotations

import hashlib
import re
from pathlib import PurePosixPath

FOUNDATION_SOURCE_INDEXES = (
    ("essential_purpose", "U1", "qa-foundation-u1"),
    ("background", "U2", "qa-foundation-u2"),
    ("goals", "U3", "qa-foundation-u3"),
    ("objectives", "U4", "qa-foundation-u4"),
    ("success_criteria", "U5", "qa-foundation-u5"),
    ("stakeholders", "U6", "qa-foundation-u6"),
    ("scope", "U7", "qa-foundation-u7"),
    ("constraints", "U8", "qa-foundation-u8"),
    ("concrete_intents", "U9", "qa-foundation-u9"),
)
SOURCE_KINDS = {"user-dialogue", "written-requirements"}
U_MARKER_RE = re.compile(r"(?<![A-Za-z0-9])U([1-9])(?![A-Za-z0-9])")
SHA256_RE = re.compile(r"^[0-9a-f]{64}$")


def _entry_by_id(qa_log) -> dict[str, dict]:
    if not isinstance(qa_log, list):
        return {}
    return {
        entry["id"]: entry
        for entry in qa_log
        if isinstance(entry, dict) and isinstance(entry.get("id"), str)
    }


def _is_relative_path(value) -> bool:
    if not isinstance(value, str) or not value.strip():
        return False
    path = PurePosixPath(value)
    return not path.is_absolute() and ".." not in path.parts and str(path) not in {"", "."}


def validate_foundation_source_indexes(data: dict) -> list[str]:
    """Return findings unless every U1--U9 has one trustworthy QA source index.

    A dialogue source keeps the exact user answer. A written source additionally
    binds its relative path, section, and SHA-256 of the recorded original text.
    These checks are deliberately content-addressed but do not read arbitrary
    user paths during validation; the state stays portable and self-contained.
    """
    entries = _entry_by_id(data.get("qa_log"))
    findings: list[str] = []
    for _field, label, entry_id in FOUNDATION_SOURCE_INDEXES:
        entry = entries.get(entry_id)
        prefix = f"requirements_foundation: {label} source-index ({entry_id})"
        if not entry:
            findings.append(f"{prefix} が qa_log に不在")
            continue
        question = entry.get("question")
        answer = entry.get("answer")
        if not isinstance(question, str) or not question.strip():
            findings.append(f"{prefix} の question が空")
        if not isinstance(answer, str) or not answer.strip():
            findings.append(f"{prefix} の answer (利用者原文) が空")
        marker_numbers = set(U_MARKER_RE.findall(question or ""))
        expected = label.removeprefix("U")
        if marker_numbers != {expected}:
            findings.append(f"{prefix} は 1論点の {label} を示す question が必要")
        source = entry.get("source")
        if not isinstance(source, dict) or source.get("kind") not in SOURCE_KINDS:
            findings.append(f"{prefix} の source.kind は {sorted(SOURCE_KINDS)} のいずれか必須")
            continue
        if source["kind"] != "written-requirements":
            continue
        path, section, digest = source.get("path"), source.get("section"), source.get("sha256")
        if not _is_relative_path(path):
            findings.append(f"{prefix} の written source.path は安全な相対パス必須")
        if not isinstance(section, str) or not section.strip():
            findings.append(f"{prefix} の written source.section が空")
        if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
            findings.append(f"{prefix} の written source.sha256 が不正")
        elif isinstance(answer, str) and hashlib.sha256(answer.encode("utf-8")).hexdigest() != digest:
            findings.append(f"{prefix} の written source.sha256 が answer 原文と不一致")
        if isinstance(question, str) and (
            (isinstance(path, str) and path not in question)
            or (isinstance(section, str) and section not in question)
        ):
            findings.append(f"{prefix} の question に written source.path と section が必要")
    return findings

